import json,subprocess
api=subprocess.check_output(['docker','ps','-q','--filter','label=com.docker.compose.project=researchhub-backend','--filter','label=com.docker.compose.service=researchhub-api'],universal_newlines=True).strip()
assert len(api.splitlines())==1
node="import{readResearchRuntimeConfig}from'./server/research-runtime/config.mjs';import{runtimeDependencies}from'./server/research-runtime/dependencies.mjs';import{bindRuntimeTransactions,withDeploymentTransaction}from'./server/database/transactions.mjs';const c=readResearchRuntimeConfig(process.env);if(c.identity.database!=='researchhub')throw Error('WRONG_DATABASE');const {load}=runtimeDependencies(c.core),p=new(load('prisma/prisma.service','PrismaService'))();try{await p.app.$connect();await p.elevated.$connect();const e=bindRuntimeTransactions({prisma:p,expected:c.identity});for(const role of ['app','direct'])console.log(JSON.stringify({role,objects:await withDeploymentTransaction(e,role,tx=>tx.$queryRawUnsafe(`SELECT to_regclass('rh_hub_asset.entry')::text AS asset_entry,to_regclass('rh_hub_asset.usage_request')::text AS usage_request,to_regclass('rh_hub_asset.copy')::text AS copy,to_regclass('public.research_member_invitation')::text AS invitations,has_schema_privilege(current_user,to_regnamespace('rh_hub_asset'),'USAGE') AS asset_usage,has_table_privilege(current_user,to_regclass('rh_hub_asset.entry'),'SELECT') AS asset_read`),{readOnly:true})}));console.log(JSON.stringify({mailMode:process.env.HUB_MAIL_MODE,invitationRoleConfigured:!!process.env.HUB_INVITATION_READER_ROLE_ID}));}finally{await p.app.$disconnect();await p.elevated.$disconnect()}"
print(subprocess.check_output(['docker','exec',api,'node','--input-type=module','-e',node],universal_newlines=True))
